#!/usr/bin/env node
/**
 * Analyzes real exported Google Forms CSV responses generated by
 * `scripts/create_google_form.gs` and outputs a clean Markdown report
 * aligned with L-easy Table I (needs assessment) and Section V-B (SUS).
 *
 * Usage:
 *   node scripts/analyze_survey_csv.mjs <path-to-responses.csv>
 *   node scripts/analyze_survey_csv.mjs --help
 */

import fs from "node:fs";
import path from "node:path";

/** Prints CLI usage instructions. */
function printHelp() {
  console.log(`Usage: node scripts/analyze_survey_csv.mjs <responses.csv>

Options:
  -h, --help    Show this help message

Expected input:
  CSV exported from the Google Sheet linked to scripts/create_google_form.gs
  (File -> Download -> Comma Separated Values (.csv)).`);
}

/**
 * Parses an RFC 4180 CSV string into a 2D array of trimmed rows.
 * Handles UTF-8 BOM, quoted fields, embedded commas, escaped quotes (""), and CRLF/LF.
 */
function parseCsv(text) {
  const clean = text.charCodeAt(0) === 0xfeff ? text.slice(1) : text;
  const rows = [];
  let row = [];
  let field = "";
  let inQuotes = false;

  for (let i = 0; i < clean.length; i++) {
    const ch = clean[i];
    if (inQuotes) {
      if (ch === '"') {
        if (clean[i + 1] === '"') {
          field += '"';
          i++;
        } else {
          inQuotes = false;
        }
      } else {
        field += ch;
      }
      continue;
    }

    if (ch === '"') {
      inQuotes = true;
    } else if (ch === ",") {
      row.push(field.trim());
      field = "";
    } else if (ch === "\r") {
      if (clean[i + 1] === "\n") i++;
      row.push(field.trim());
      if (row.some((cell) => cell !== "")) rows.push(row);
      row = [];
      field = "";
    } else if (ch === "\n") {
      row.push(field.trim());
      if (row.some((cell) => cell !== "")) rows.push(row);
      row = [];
      field = "";
    } else {
      field += ch;
    }
  }

  if (field !== "" || row.length > 0) {
    row.push(field.trim());
    if (row.some((cell) => cell !== "")) rows.push(row);
  }
  return rows;
}

/** Finds the first header index matching any candidate substring (case-insensitive). */
function findColumnIndex(headers, matchers) {
  return headers.findIndex((h) => {
    const low = h.toLowerCase();
    return matchers.some((m) => (m instanceof RegExp ? m.test(h) : low.includes(m)));
  });
}

/** Maps all expected survey headers dynamically without hardcoding column letters. */
function mapColumns(headers) {
  const sus = [];
  for (let k = 1; k <= 10; k++) {
    const idx = findColumnIndex(headers, [new RegExp(`\\bsus\\s*${k}\\b`, "i")]);
    sus.push(idx);
  }

  return {
    timestamp: findColumnIndex(headers, ["timestamp", "отметка времени"]),
    consent: findColumnIndex(headers, ["informed consent", "информированное согласие"]),
    ageGate: findColumnIndex(headers, ["18 years", "исполнилось 18"]),
    age: findColumnIndex(headers, ["your age", "ваш возраст"]),
    year: findColumnIndex(headers, ["year of study", "курс обучения"]),
    major: findColumnIndex(headers, ["major", "образовательная программа"]),
    fallBehind: findColumnIndex(headers, ["simultaneously", "одновременно слушать"]),
    reListen: findColumnIndex(headers, ["re-listen", "переслушиваете"]),
    stemTerms: findColumnIndex(headers, ["stem", "терминами"]),
    stress: findColumnIndex(headers, ["stress", "стресса"]),
    integratedTool: findColumnIndex(headers, ["integrated lecture assistant", "единый инструмент"]),
    device: findColumnIndex(headers, ["device used", "устройстве"]),
    completedFlow: findColumnIndex(headers, ["5-step", "5-шаговый"]),
    sus,
    satisfaction: findColumnIndex(headers, ["satisfaction", "удовлетворённость", "удовлетворенность"]),
    recommend: findColumnIndex(headers, ["recommend", "порекомендовали"]),
  };
}

/** Parses common Google Forms timestamps (ISO, M/D/YYYY H:MM:SS, DD.MM.YYYY H:MM:SS). */
function parseTimestampMs(raw) {
  if (!raw) return Number.NaN;
  const ruMatch = raw.match(
    /^(\d{1,2})\.(\d{1,2})\.(\d{4})(?:\s+(\d{1,2}):(\d{2})(?::(\d{2}))?)?$/,
  );
  if (ruMatch) {
    const [, dd, mm, yyyy, hh = "0", mi = "0", ss = "0"] = ruMatch;
    return Date.UTC(Number(yyyy), Number(mm) - 1, Number(dd), Number(hh), Number(mi), Number(ss));
  }
  const parsed = Date.parse(raw);
  return Number.isNaN(parsed) ? Number.NaN : parsed;
}

/** Computes summary stats with sample SD (n - 1 denominator). */
function summarizeNumbers(values) {
  if (values.length === 0) return null;
  const n = values.length;
  const sum = values.reduce((a, b) => a + b, 0);
  const mean = sum / n;
  const min = Math.min(...values);
  const max = Math.max(...values);
  let sd = null;
  if (n > 1) {
    const variance = values.reduce((acc, v) => acc + (v - mean) ** 2, 0) / (n - 1);
    sd = Math.sqrt(variance);
  }
  return { n, mean, sd, min, max };
}

/** Formats count and percentage cleanly. */
function fmtPct(count, total) {
  if (total === 0) return `${count}/0 (0.0%)`;
  return `${count}/${total} (${((count / total) * 100).toFixed(1)}%)`;
}

/** Formats mean +/- sample SD cleanly. */
function fmtMeanSd(stats, decimals = 1) {
  if (!stats) return "N/A";
  const sdStr = stats.sd === null ? "N/A (n=1)" : stats.sd.toFixed(decimals);
  return `${stats.mean.toFixed(decimals)} ± ${sdStr} (range ${stats.min.toFixed(decimals)}–${stats.max.toFixed(decimals)})`;
}

/** Checks whether an answer starts with Russian "Да" or English "Yes" (option matching). */
function matchesPrefix(value, prefixes) {
  const low = (value || "").trim().toLowerCase();
  return prefixes.some((p) => low.includes(p.toLowerCase()));
}

/** Tallies categorical values into sorted [label, count] pairs. */
function tallyCategories(rows, colIdx) {
  const map = new Map();
  if (colIdx < 0) return [];
  for (const r of rows) {
    const val = (r[colIdx] || "").trim() || "(blank)";
    map.set(val, (map.get(val) || 0) + 1);
  }
  return [...map.entries()].sort((a, b) => b[1] - a[1]);
}

/** Computes Brooke (1996) SUS score [0..100] when all 10 items are valid 1..5 integers. */
function computeBrookeSus(row, susCols) {
  if (susCols.some((idx) => idx < 0)) return null;
  let total = 0;
  for (let i = 0; i < 10; i++) {
    const raw = (row[susCols[i]] || "").trim();
    const score = Number(raw);
    if (!Number.isInteger(score) || score < 1 || score > 5) return null;
    total += i % 2 === 0 ? score - 1 : 5 - score;
  }
  return total * 2.5;
}

/** Validates consent, 18+ gate, and numeric age >= 18 for an individual row. */
function validateRow(row, cols) {
  const consentVal = cols.consent >= 0 ? row[cols.consent] || "" : "";
  if (!consentVal || matchesPrefix(consentVal, ["нет / no"])) {
    return { ok: false, reason: "missing_consent" };
  }

  const gateVal = cols.ageGate >= 0 ? row[cols.ageGate] || "" : "";
  const gateYes = matchesPrefix(gateVal, ["да, мне 18", "yes, i am 18"]);
  const gateNo = matchesPrefix(gateVal, ["меньше 18", "under 18"]);
  if (!gateYes || gateNo) {
    return { ok: false, reason: "under_18_gate" };
  }

  const ageRaw = cols.age >= 0 ? (row[cols.age] || "").trim() : "";
  const ageNum = Number(ageRaw);
  if (!ageRaw || !Number.isFinite(ageNum) || ageNum < 18 || ageNum > 120) {
    return { ok: false, reason: "invalid_age" };
  }

  return { ok: true, ageNum };
}

/** Analyzes parsed CSV data and prints a concise Markdown summary report. */
function analyzeSurvey(csvPath) {
  const raw = fs.readFileSync(csvPath, "utf8");
  const table = parseCsv(raw);
  if (table.length < 2) {
    console.error("CSV contains no response rows.");
    process.exit(1);
  }

  const headers = table[0];
  const dataRows = table.slice(1);
  const cols = mapColumns(headers);

  const missingCritical = ["consent", "ageGate", "age"].filter((k) => cols[k] < 0);
  if (missingCritical.length > 0) {
    console.error(`Missing required columns (${missingCritical.join(", ")}). Is this CSV from create_google_form.gs?`);
    process.exit(1);
  }

  const validRows = [];
  const ages = [];
  const excludedCounts = { missing_consent: 0, under_18_gate: 0, invalid_age: 0 };

  for (const row of dataRows) {
    const check = validateRow(row, cols);
    if (!check.ok) {
      excludedCounts[check.reason]++;
      continue;
    }
    validRows.push(row);
    ages.push(check.ageNum);
  }

  const excludedTotal = dataRows.length - validRows.length;
  const ageStats = summarizeNumbers(ages);

  // Extract timestamp range from valid adult consenting responses
  const rawTimestamps =
    cols.timestamp >= 0
      ? validRows.map((r) => (r[cols.timestamp] || "").trim()).filter(Boolean)
      : [];
  const stamped = rawTimestamps.map((str) => ({ str, ms: parseTimestampMs(str) }));
  const numericStamped = stamped.filter((t) => Number.isFinite(t.ms)).sort((a, b) => a.ms - b.ms);
  const earliestTs =
    numericStamped.length > 0 ? numericStamped[0].str : rawTimestamps[0] || "N/A";
  const latestTs =
    numericStamped.length > 0
      ? numericStamped[numericStamped.length - 1].str
      : rawTimestamps[rawTimestamps.length - 1] || "N/A";

  // Needs Assessment (Table I metrics)
  const nValid = validRows.length;
  const countMatch = (colIdx, needles) =>
    colIdx < 0 ? 0 : validRows.filter((r) => matchesPrefix(r[colIdx], needles)).length;

  const fallOften = countMatch(cols.fallBehind, ["часто не успеваю", "often fall behind"]);
  const fallSometimes = countMatch(cols.fallBehind, ["иногда не успеваю", "sometimes fall behind"]);
  const reListenNever = countMatch(cols.reListen, ["никогда", "never"]);
  const reListenRarely = countMatch(cols.reListen, ["редко", "rarely"]);
  const reListenFreq = countMatch(cols.reListen, ["часто", "frequently"]);
  const stemOften = countMatch(cols.stemTerms, ["да, часто", "yes, often"]);
  const stemSometimes = countMatch(cols.stemTerms, ["иногда", "sometimes"]);
  const stressScores =
    cols.stress >= 0
      ? validRows.map((r) => Number(r[cols.stress])).filter((v) => Number.isFinite(v) && v >= 1 && v <= 5)
      : [];
  const highStressCount = stressScores.filter((v) => v >= 4).length;
  const wantToolYes = countMatch(cols.integratedTool, ["да / yes"]);
  const wantToolProb = countMatch(cols.integratedTool, ["скорее да", "probably yes"]);

  // Usability Sub-Cohort (exclude respondents who selected "Did not test prototype")
  const testedRows =
    cols.device >= 0
      ? validRows.filter((r) => {
          const dev = (r[cols.device] || "").trim();
          return dev !== "" && !matchesPrefix(dev, ["не тестировал", "did not test"]);
        })
      : [];

  const nTested = testedRows.length;
  const completedFull =
    cols.completedFlow >= 0
      ? testedRows.filter((r) => matchesPrefix(r[cols.completedFlow], ["да, полностью", "yes, completed"])).length
      : 0;
  const completedPartial =
    cols.completedFlow >= 0
      ? testedRows.filter((r) => matchesPrefix(r[cols.completedFlow], ["частично", "partially"])).length
      : 0;

  const susScores = testedRows.map((r) => computeBrookeSus(r, cols.sus)).filter((v) => v !== null);
  const susStats = summarizeNumbers(susScores);
  const satScores =
    cols.satisfaction >= 0
      ? testedRows
          .map((r) => Number(r[cols.satisfaction]))
          .filter((v) => Number.isFinite(v) && v >= 1 && v <= 5)
      : [];
  const satStats = summarizeNumbers(satScores);
  const recommendYes =
    cols.recommend >= 0
      ? testedRows.filter((r) => matchesPrefix(r[cols.recommend], ["да / yes"])).length
      : 0;

  // Build Markdown output
  const lines = [];
  lines.push(`# L-easy Survey Analysis Report (${path.basename(csvPath)})`);
  lines.push("");
  lines.push("## 1. Sample & Consent Audit");
  lines.push(`- **Total CSV rows:** ${dataRows.length}`);
  lines.push(`- **Valid consenting 18+ respondents:** ${nValid}`);
  lines.push(
    `- **Excluded rows:** ${excludedTotal} (under-18 gate: ${excludedCounts.under_18_gate}, missing consent: ${excludedCounts.missing_consent}, invalid/under-18 age: ${excludedCounts.invalid_age})`,
  );
  lines.push(`- **Earliest Google Forms timestamp:** \`${earliestTs}\``);
  lines.push(`- **Latest Google Forms timestamp:** \`${latestTs}\``);
  lines.push(`- **Age (years, n=${nValid}):** ${fmtMeanSd(ageStats, 1)}`);

  if (nValid > 0) {
    lines.push("");
    lines.push("### Demographics (Valid 18+ Cohort)");
    for (const [label, c] of tallyCategories(validRows, cols.year)) {
      lines.push(`- Year — ${label}: ${fmtPct(c, nValid)}`);
    }
    for (const [label, c] of tallyCategories(validRows, cols.major)) {
      lines.push(`- Major — ${label}: ${fmtPct(c, nValid)}`);
    }

    lines.push("");
    lines.push(`## 2. Needs Assessment (Table I Metrics, N = ${nValid})`);
    lines.push(`- **Cannot listen & write simultaneously (Often fall behind):** ${fmtPct(fallOften, nValid)}`);
    lines.push(`- **Fall behind Often OR Sometimes:** ${fmtPct(fallOften + fallSometimes, nValid)}`);
    lines.push(
      `- **Raw 50-min audio re-listening:** Never ${fmtPct(reListenNever, nValid)} | Rarely ${fmtPct(reListenRarely, nValid)} | Frequently ${fmtPct(reListenFreq, nValid)}`,
    );
    lines.push(
      `- **EN/RU/KZ STEM term gap:** Often ${fmtPct(stemOften, nValid)} | Often or Sometimes ${fmtPct(stemOften + stemSometimes, nValid)}`,
    );
    lines.push(
      `- **High midterm/exam stress (4–5/5):** ${fmtPct(highStressCount, stressScores.length)} (mean ${fmtMeanSd(summarizeNumbers(stressScores), 2)})`,
    );
    lines.push(
      `- **Want integrated assistant:** Yes ${fmtPct(wantToolYes, nValid)} | Yes or Probably ${fmtPct(wantToolYes + wantToolProb, nValid)}`,
    );

    lines.push("");
    lines.push(`## 3. Prototype Usability & Standard Brooke SUS (Tested Sub-Cohort, N = ${nTested})`);
    if (nTested === 0) {
      lines.push("- No respondents selected a tested prototype device yet.");
    } else {
      lines.push(`- **5-step flow completion (Full):** ${fmtPct(completedFull, nTested)} (Partial: ${fmtPct(completedPartial, nTested)})`);
      lines.push(`- **Brooke SUS score (n=${susScores.length} complete 10-item responses):** ${fmtMeanSd(susStats, 1)}`);
      lines.push(`- **Overall satisfaction (1–5):** ${fmtMeanSd(satStats, 2)}`);
      lines.push(`- **Peer recommendation (Yes):** ${fmtPct(recommendYes, nTested)}`);
      lines.push("- **Devices tested:**");
      for (const [label, c] of tallyCategories(testedRows, cols.device)) {
        lines.push(`  - ${label}: ${fmtPct(c, nTested)}`);
      }
    }
  }

  console.log(lines.join("\n"));
}

function main() {
  const args = process.argv.slice(2);
  if (args.length === 0 || args.includes("--help") || args.includes("-h")) {
    printHelp();
    process.exit(0);
  }
  const target = path.resolve(args[0]);
  if (!fs.existsSync(target)) {
    console.error(`File not found: ${target}`);
    process.exit(1);
  }
  analyzeSurvey(target);
}

main();
